        group.MapPut("/registers/{registerId:guid}", async (Guid registerId, UpdateRegisterRequest request, HttpContext http, PosService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await ResourceAccessAsync(http, service, subjects, authorizer, "pos.register.manage", "register", registerId, ct), () => service.UpdateRegisterAsync(Tenant(http), registerId, request, ct)));
        group.MapPost("/registers/{registerId:guid}/activate", async (Guid registerId, HttpContext http, PosService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await ResourceAccessAsync(http, service, subjects, authorizer, "pos.register.manage", "register", registerId, ct), () => service.ChangeRegisterStatusAsync(Tenant(http), registerId, "Active", ct)));
        group.MapPost("/registers/{registerId:guid}/deactivate", async (Guid registerId, HttpContext http, PosService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await ResourceAccessAsync(http, service, subjects, authorizer, "pos.register.manage", "register", registerId, ct), () => service.ChangeRegisterStatusAsync(Tenant(http), registerId, "Disabled", ct)));
        group.MapPost("/registers/{registerId:guid}/terminals", async (Guid registerId, RegisterTerminalRequest request, HttpContext http, PosService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await ResourceAccessAsync(http, service, subjects, authorizer, "pos.register.manage", "register", registerId, ct), () => service.RegisterTerminalAsync(Tenant(http), registerId, request, ct), StatusCodes.Status201Created));
        group.MapPost("/terminals/register", async (RegisterTerminalRequest request, HttpContext http, PosService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await ResourceAccessAsync(http, service, subjects, authorizer, "pos.register.manage", "register", request.RegisterId, ct), () => service.RegisterTerminalAsync(Tenant(http), request.RegisterId, request, ct), StatusCodes.Status201Created));
        group.MapPost("/terminals/{terminalId:guid}/rotate-credential", async (Guid terminalId, HttpContext http, PosService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await ResourceAccessAsync(http, service, subjects, authorizer, "pos.register.manage", "terminal", terminalId, ct), () => service.ChangeTerminalAsync(Tenant(http), terminalId, "rotate", ct)));
        group.MapPost("/terminals/{terminalId:guid}/revoke", async (Guid terminalId, HttpContext http, PosService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await ResourceAccessAsync(http, service, subjects, authorizer, "pos.register.manage", "terminal", terminalId, ct), () => service.ChangeTerminalAsync(Tenant(http), terminalId, "revoke", ct)));
        group.MapPost("/terminals/{terminalId:guid}/heartbeat", async (Guid terminalId, HttpContext http, PosService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await ResourceAccessAsync(http, service, subjects, authorizer, "pos.register.manage", "terminal", terminalId, ct), () => service.ChangeTerminalAsync(Tenant(http), terminalId, "heartbeat", ct)));
